import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import api from '../services/api';
const API_ROOT = (api.defaults.baseURL || '').replace(/\/api\/?$/, '');
export default {
  name: 'CustomerProducts',
  data() {
    return {
      products: [],
      q: '',
      storeOwnerId: 0,
      stores: [],
      debounceTimer: null
    };
  },
  async created() {
    await this.fetchStores();
    await this.fetchProducts();
  },
  methods: {
    async fetchStores() {
      // Derive store list from all active products returned by customer endpoint
      const resp = await api.get('/customer/products');
      const uniq = {};
      resp.data.forEach(p => {
        if (p.store_owner_id) uniq[p.store_owner_id] = true;
      });
      this.stores = Object.keys(uniq).map(id => ({
        id: Number(id),
        store_name: `Store ${id}`
      }));
    },
    async fetchProducts() {
      const params = {};
      if (this.q) params.q = this.q;
      if (this.storeOwnerId) params.storeOwnerId = this.storeOwnerId;
      const {
        data
      } = await api.get('/customer/products', {
        params
      });
      this.products = data;
    },
    debouncedFetch() {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => this.fetchProducts(), 300);
    },
    add(p) {
      this.$store.dispatch('addToCart', {
        product_id: p.id,
        name: this.productLabel(p),
        unit_price: p.price,
        quantity: 1,
        store_owner_id: p.store_owner_id
      });
    },
    toPublicImageUrl(imageUrl) {
      if (!imageUrl) return '';
      if (/^https?:\/\//i.test(imageUrl)) return imageUrl;
      return `${API_ROOT}${imageUrl.startsWith('/') ? '' : '/'}${imageUrl}`;
    },
    productLabel(p) {
      return p.description || '—';
    },
    fmt(v) {
      const n = Number(v);
      return isFinite(n) ? n.toFixed(2) : '0.00';
    }
  }
};
